use std::{collections::BTreeMap, path::PathBuf};

use dust_cache::CacheEntry;
use dust_diagnostics::Diagnostic;
use dust_emitter::WriteResult;
use dust_workspace::SourceLibrary;

use crate::result::{BuildArtifact, DiagnosticFile};

use super::{BuildOutcome, IndexedBuildOutcome, SuccessfulBuildOutcome};

/// Fresh emitted digests keyed by the source library that produced them.
pub(crate) type OutputSnapshots = BTreeMap<PathBuf, OutputSnapshot>;

/// Current generated bytes, retained as digests rather than duplicate source text.
pub(crate) struct OutputSnapshot {
    /// Ordered output-set identity attached by the emitter.
    expected_output_hash: u64,
    /// Present nonempty primary followed by the ordered auxiliary outputs.
    files: Vec<(PathBuf, Option<u64>)>,
}

impl OutputSnapshot {
    /// Empty or suppressed primaries require the existing live presence check.
    pub(crate) fn from_output(output: &WriteResult, write_output: bool) -> Option<Self> {
        if !write_output
            || output.source.is_empty()
            || output.suppress_primary_output
            || output.diagnostics.iter().any(Diagnostic::is_error)
        {
            return None;
        }
        Some(Self {
            expected_output_hash: output.output_hash,
            files: std::iter::once((&output.output_path, output.source.as_str()))
                .chain(
                    output
                        .auxiliary_outputs
                        .iter()
                        .map(|output| (&output.output_path, output.source.as_str())),
                )
                .map(|(path, source)| (path.clone(), Some(crate::build::hash_text(source))))
                .collect(),
        })
    }

    /// Cache identity and the complete ordered artifact paths remain authoritative.
    pub(crate) fn matching_files(
        &self,
        artifact: &BuildArtifact,
        entry: &CacheEntry,
    ) -> Option<&[(PathBuf, Option<u64>)]> {
        if self.expected_output_hash != entry.expected_output_hash
            || entry.suppress_primary_output
            || entry.auxiliary_output_paths != artifact.auxiliary_output_paths
            || !self
                .files
                .iter()
                .map(|(path, _)| path)
                .eq(std::iter::once(&artifact.output_path).chain(&artifact.auxiliary_output_paths))
            || self.files.iter().any(|(_, hash)| hash.is_none())
            || self.files.first()?.1 == Some(crate::build::hash_text(""))
        {
            return None;
        }
        Some(&self.files)
    }
}

/// Moves fresh facts before the public result consumes the internal outcomes.
pub(crate) fn collect_output_snapshots(outcomes: &mut [IndexedBuildOutcome]) -> OutputSnapshots {
    outcomes
        .iter_mut()
        .filter_map(|outcome| {
            outcome
                .outcome
                .output_snapshot
                .take()
                .map(|snapshot| (outcome.library.source_path.clone(), snapshot))
        })
        .collect()
}

/// Combines emitter results with diagnostics into a successful build outcome.
pub(super) fn finish_success(
    library: &SourceLibrary,
    mut diagnostics: Vec<Diagnostic>,
    diagnostic_file: Option<DiagnosticFile>,
    output: WriteResult,
    write_output: bool,
) -> BuildOutcome {
    let output_snapshot = OutputSnapshot::from_output(&output, write_output);
    let WriteResult {
        source: _,
        output_hash,
        symbols: _,
        diagnostics: output_diagnostics,
        changed,
        written,
        output_path: _,
        suppress_primary_output,
        auxiliary_outputs,
    } = output;
    diagnostics.extend(output_diagnostics);

    BuildOutcome::succeeded(
        library,
        SuccessfulBuildOutcome {
            diagnostics,
            diagnostic_file,
            expected_output_hash: output_hash,
            output_snapshot,
            auxiliary_output_paths: auxiliary_outputs
                .into_iter()
                .map(|output| output.output_path)
                .collect(),
            suppress_primary_output,
            changed,
            written,
        },
    )
}
